export const NEWSLETTER_BODY_SCRIPT = "\n  (function () {\n    'use strict';\n\n    var root = document.documentElement;\n    var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');\n    var narrow = window.matchMedia('(max-width: 1099.98px)');\n    var hasObserver = 'IntersectionObserver' in window;\n\n    /* ── الحركة عند الظهور ── */\n    var revealEls = [].slice.call(document.querySelectorAll('.reveal'));\n    function revealAll() {\n      revealEls.forEach(function (el) { el.classList.add('is-visible'); });\n    }\n    if (root.classList.contains('reveal-ready')) {\n      var revealer = new IntersectionObserver(function (entries) {\n        entries.forEach(function (entry) {\n          if (!entry.isIntersecting) return;\n          entry.target.classList.add('is-visible');\n          revealer.unobserve(entry.target);\n        });\n      }, { rootMargin: '0px 0px -8% 0px' });\n      revealEls.forEach(function (el) { revealer.observe(el); });\n    }\n    window.addEventListener('beforeprint', revealAll);\n\n    /* ── شريط تقدّم القراءة ── */\n    var progress = document.querySelector('.progress');\n    var lastPercent = -1;\n    var ticking = false;\n    function updateProgress() {\n      ticking = false;\n      var max = root.scrollHeight - window.innerHeight;\n      var ratio = max > 0 ? Math.min(Math.max(window.scrollY / max, 0), 1) : 0;\n      progress.style.setProperty('--progress', ratio.toFixed(4));\n      var percent = Math.round(ratio * 100);\n      if (percent !== lastPercent) {\n        progress.setAttribute('aria-valuenow', String(percent));\n        lastPercent = percent;\n      }\n    }\n    function requestProgress() {\n      if (ticking) return;\n      ticking = true;\n      window.requestAnimationFrame(updateProgress);\n    }\n    window.addEventListener('scroll', requestProgress, { passive: true });\n    window.addEventListener('resize', requestProgress);\n    updateProgress();\n\n    /* ── فهرس المحتويات ── */\n    var toc = document.querySelector('.toc');\n    var toggle = toc.querySelector('.toc-toggle');\n    var list = toc.querySelector('.toc-list');\n    var current = toc.querySelector('.toc-current');\n    var links = [].slice.call(toc.querySelectorAll('.toc-link'));\n    var activeLink = null;\n\n    function isCollapsed() { return toc.classList.contains('is-collapsed'); }\n\n    // يُبقي الرابط النشط ظاهرًا داخل الشريط الأفقي على الشاشات الصغيرة\n    function centerActiveChip() {\n      if (!activeLink || !narrow.matches || isCollapsed()) return;\n      var item = activeLink.parentElement;\n      list.scrollTo({\n        left: item.offsetLeft + item.offsetWidth / 2 - list.clientWidth / 2,\n        behavior: reduceMotion.matches ? 'auto' : 'smooth'\n      });\n    }\n\n    function setExpanded(open) {\n      toc.classList.toggle('is-collapsed', !open);\n      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');\n      if (open) centerActiveChip();\n    }\n\n    setExpanded(false);\n    toggle.addEventListener('click', function () { setExpanded(isCollapsed()); });\n    toc.addEventListener('keydown', function (event) {\n      if (event.key === 'Escape' && narrow.matches && !isCollapsed()) {\n        setExpanded(false);\n        toggle.focus();\n      }\n    });\n    links.forEach(function (link) {\n      link.addEventListener('click', function () { if (narrow.matches) setExpanded(false); });\n    });\n\n    var sections = links.map(function (link) {\n      return document.getElementById(link.getAttribute('href').slice(1));\n    });\n\n    function setActive(id) {\n      var next = null;\n      links.forEach(function (link, i) {\n        if (sections[i] && sections[i].id === id) {\n          link.setAttribute('aria-current', 'location');\n          next = link;\n        } else {\n          link.removeAttribute('aria-current');\n        }\n      });\n      if (next === activeLink) return;\n      activeLink = next;\n      current.textContent = next ? next.textContent : '';\n      centerActiveChip();\n    }\n\n    // القسم النشط = آخر قسم تجاوز بدايته ثلث الشاشة العلوي.\n    // يُحسب من الموضع الفعلي حتى لا تُفوَّت الأقسام عند القفز (End، روابط الفهرس).\n    function syncActive() {\n      var line = window.innerHeight * 0.35;\n      var id = null;\n      sections.forEach(function (section) {\n        if (section && section.getBoundingClientRect().top <= line) id = section.id;\n      });\n      setActive(id);\n    }\n\n    if (hasObserver) {\n      var spy = new IntersectionObserver(syncActive, { rootMargin: '0px 0px -65% 0px' });\n      sections.forEach(function (section) { if (section) spy.observe(section); });\n    }\n  })();\n";
